    <tr><td>10.472</td><td>0.9</td><td>4.813</td><td>24.06</td><td>0.4471</td><td>53.82</td><td>9.954</td><td>7.273</td><td>0.7307</td><td>7.85&#8239;×&#8239;10<sup>−7</sup></td></tr>
